// 每日認養毛孩 petDaily(SERVER)
// 資料來源:WebAPI 連線 ADOPT_PET → 農業部「動物認領養」開放資料
// 每天(Asia/Taipei)抽一筆 → 用 $setDeviceProperty 改連線網址的 $skip → $getDevice().polling() 立即讀取 → 檢查後組卡片
const fs = require('fs');
const path = require('path');
const g = global.__petDaily || (global.__petDaily = {});
const DIR = path.join(process.cwd(), '_petdaily');
const FILE = path.join(DIR, 'state.json');
const DEV = 'ADOPT_PET';
const URL_OF = (skip) => 'https://data.moa.gov.tw/Service/OpenData/TransService.aspx?UnitId=QcbUEzN6E6DL&animal_status=OPEN&$top=1&$skip=' + skip;
const MAX_TRIES = 12, EMPTY_MS = 15000;

if (!g.state) {
    try { g.state = JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch (e) { g.state = { target: 0, card: null, history: [], pool: 1500, pending: false, prevId: null, tries: 0, push: 0 }; }
}
const st = g.state;
const save = () => { try { fs.mkdirSync(DIR, { recursive: true }); fs.writeFileSync(FILE, JSON.stringify(st, null, 1)); } catch (e) { console.error('pet save', e.message); } };
const put = async (id, v) => { if ($getTag(id) !== v) await $setTag(id, v); };
const now = Date.now();
const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Taipei' });
const cmd = Number($getTag('t_pad_cmd')) === 1;

function pick() {
    let skip = 0;
    for (let k = 0; k < 20; k++) {
        skip = Math.floor(Math.random() * st.pool);
        if (skip !== st.target) break;
    }
    st.target = skip;
    st.pending = true;
    st.prevId = $getTag('t_pa_id');
    st.tries = (st.tries || 0) + 1;
    g.appliedAt = now;
    g.lastPoll = 0;
    save();
}
async function stop() {
    st.pending = false;
    st.tries = 0;
    g.cmdTaken = false;
    save();
    if (Number($getTag('t_pad_cmd')) === 1) await $setTag('t_pad_cmd', 0);
}
async function retry() {
    if ((st.tries || 0) >= MAX_TRIES) { g.failAt = now; await stop(); } else pick();
}

// 1) 決定要不要換一筆
const expired = !st.card || st.card.date !== today || st.card.since === undefined;
if (!st.pending && ((expired && now - (g.failAt || 0) > 60000) || (cmd && !g.cmdTaken))) {
    if (cmd) g.cmdTaken = true;
    st.tries = 0;
    pick();
}

// 2) 把目標寫進 WebAPI 連線網址,讀取回應
if (st.pending) {
    g.appliedAt = g.appliedAt || now;
    const url = URL_OF(st.target);
    const p = $getDeviceProperty(DEV);
    if (p && p.address !== url) {
        $setDeviceProperty(DEV, Object.assign({}, p, { address: url, method: 'GET', format: 'JSON' }));
        g.appliedAt = now;
        g.lastPoll = 0;
    }
    const id = $getTag('t_pa_id');
    if (id !== null && id !== undefined && id !== st.prevId) {
        const photo = String($getTag('t_pa_photo') || '').trim();
        const open = String($getTag('t_pa_open') || '').trim();
        const recent = (st.history || []).slice(0, 30).map(h => h.id);
        // 沒有照片、尚未開放認養、最近抽過 → 換下一筆
        if (!photo || (open && open > today) || recent.indexOf(id) >= 0) {
            await retry();
        } else {
            const SEX = { M: '公', F: '母', N: '未知' };
            const BODY = { SMALL: '小型', MEDIUM: '中型', BIG: '大型' };
            const AGE = { CHILD: '幼年', ADULT: '成年' };
            const YN = { T: '已完成', F: '尚未', N: '未確認' };
            const text = (t) => String($getTag(t) || '').trim();
            st.card = {
                id, sub: text('t_pa_subid'), kind: text('t_pa_kind'), variety: text('t_pa_variety') || text('t_pa_kind'),
                sex: SEX[text('t_pa_sex')] || '未知', body: BODY[text('t_pa_body')] || '未知', age: AGE[text('t_pa_age')] || '未知',
                colour: text('t_pa_colour') || '未知', ster: YN[text('t_pa_ster')] || '未確認', bact: YN[text('t_pa_bact')] || '未確認',
                shelter: text('t_pa_shelter'), tel: text('t_pa_tel'), addr: text('t_pa_addr'), update: text('t_pa_update'),
                photo, date: today,
                since: open || text('t_pa_create').replace(/\//g, '-'), sinceField: open ? 'animal_opendate' : 'animal_createtime', sinceTag: open ? 't_pa_open' : 't_pa_create',
                // 透視模式顯示 API 原始值
                raw: { kind: text('t_pa_kind'), variety: text('t_pa_variety'), sex: text('t_pa_sex'), body: text('t_pa_body'), age: text('t_pa_age'),
                    colour: text('t_pa_colour'), ster: text('t_pa_ster'), bact: text('t_pa_bact'), since: open || text('t_pa_create') },
                api: 'GET ' + URL_OF(st.target).replace('https://', '')
            };
            st.push = now;
            st.history = [{ id, date: today }].concat((st.history || []).filter(h => h.id !== id)).slice(0, 120);
            await stop();
        }
    } else if (now - g.appliedAt > EMPTY_MS) {
        // 超過資料筆數時 API 回空陣列,WebAPI 不會更新 tag → 縮小抽選範圍再試
        st.pool = Math.max(200, Math.floor(st.target * 0.8));
        await retry();
    } else if (now - g.appliedAt > 2500 && now - (g.lastPoll || 0) > 6000) {
        g.lastPoll = now;
        try { const d = $getDevice(DEV); if (d && d.polling) d.polling(); } catch (e) { console.error('pet poll', e.message); }
    }
}

// 3) 輸出到 FUXA Server tags
await put('t_pad_btn', st.pending ? '◌  正在找…' : '↻  換一隻');
const c = st.card;
if (c) {
    const [y, m, d] = c.date.split('-');
    await put('t_pad_day', y + ' · ' + m + ' · ' + d);
    // 等家天數:開放認養日到今天
    const days = /^\d{4}-\d{2}-\d{2}/.test(c.since) ? Math.floor((Date.parse(c.date) - Date.parse(c.since.slice(0, 10))) / 86400000) : -1;
    await put('t_pad_pre', days > 0 ? '已經等了' : (days === 0 ? '今天開始等一個家' : '正在等一個家'));
    await put('t_pad_num', days > 0 ? String(days) : '');
    await put('t_pad_post', days > 0 ? '天' : '');
    await put('t_pad_kind', c.kind);
    await put('t_pad_variety', c.variety);
    await put('t_pad_line', '我在「' + c.shelter + '」等你');
    await put('t_pad_sex', c.sex);
    await put('t_pad_body', c.body);
    await put('t_pad_age', c.age);
    await put('t_pad_colour', c.colour);
    await put('t_pad_ster', c.ster);
    await put('t_pad_bact', c.bact);
    await put('t_pad_shelter', c.shelter);
    await put('t_pad_tel', c.tel);
    await put('t_pad_addr', c.addr.replace(/[（(]\s*座標.*?[）)]/g, '').trim());
    await put('t_pad_sub', '收容編號  ' + (c.sub || c.id));
    await put('t_pad_count', '資料更新 ' + c.update + '  ·  已介紹 ' + (st.history || []).length + ' 隻');
    await put('t_pad_json', JSON.stringify(Object.assign({ push: st.push, busy: !!st.pending }, c)));
}

// 每日認養毛孩 petUI(CLIENT):換卡同步、等家天數排版、長文字縮字、JSON 透視模式
// 只在執行畫面跑:編輯器裡跑會改動畫面,存檔時把照片網址、隱藏狀態寫進專案
if (!window.__petUI && location.pathname.indexOf('/editor') < 0 && location.pathname.indexOf('/lab') < 0) {
  window.__petUI = true;
  const svc = this;
  const NS = 'http://www.w3.org/2000/svg';
  const css = document.createElement('style');
  css.textContent = `
  .pa-fade { transition: opacity .45s ease; }
  .pa-fade.pa-dim { opacity: .18; }
  .pa-fade.pa-hold { opacity: 0 !important; transition: none !important; }
  #pa-photo { transition: filter 1.1s ease; }
  #pa-photo.pa-dev { filter: sepia(1) brightness(1.5) contrast(.55) blur(6px); }
  #pa-official a { color: #8a4b1f; font: 700 17px 'Microsoft JhengHei','Segoe UI',sans-serif; text-decoration: none; letter-spacing: .06em; }
  #pa-official a:hover { text-decoration: underline; }`;
  document.head.appendChild(css);

  // 清掉被舊編輯器存進 SVG 的執行狀態
  const cleanBaked = () => {
    document.querySelectorAll('[data-on],[data-key]').forEach((e) => { e.removeAttribute('data-on'); e.removeAttribute('data-key'); });
    document.querySelectorAll('.pa-hold,.pa-dim,.pa-dev').forEach((e) => e.classList.remove('pa-hold', 'pa-dim', 'pa-dev'));
  };

  let card = null, xray = false, swapping = false, observed = null, lastText = null;
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const fades = (cls, on) => document.querySelectorAll('.pa-fade').forEach((e) => e.classList.toggle(cls, on));
  const href = (el, url) => { el.setAttribute('href', url); el.setAttributeNS('http://www.w3.org/1999/xlink', 'href', url); };
  const textOf = (id) => document.querySelector('#' + id + ' text');
  const fit = (id, maxW, base) => {
    const t = textOf(id);
    if (!t || !t.textContent) return;
    t.setAttribute('font-size', base);
    const w = t.getComputedTextLength();
    if (w > maxW) t.setAttribute('font-size', Math.max(11, Math.floor(base * maxW / w)));
  };
  const placeX = (t, x) => { t.setAttribute('x', x); t.querySelectorAll('tspan').forEach((s) => s.setAttribute('x', x)); };

  // 「已經等了 87 天」三段文字依實際寬度接續排列
  function layoutWait() {
    const pre = textOf('VAL_pa_pre'), num = textOf('VAL_pa_num'), post = textOf('VAL_pa_post');
    if (!pre || !num || !post) return;
    let x = 690 + pre.getComputedTextLength() + 14;
    placeX(num, x);
    x += num.getComputedTextLength() + 10;
    placeX(post, x);
  }
  function fitAll() {
    fit('VAL_pa_variety', 440, 28);
    fit('VAL_pa_line', 530, 24);
    fit('VAL_pa_shelter', 430, 22);
    fit('VAL_pa_addr', 430, 16);
    fit('VAL_pa_sub', 480, 19);
    layoutWait();
  }

  // 文字一變動就先藏起來(在瀏覽器繪製前),等新照片備妥再一起顯示
  function watch() {
    const t = textOf('VAL_pa_sub');
    if (!t || t === observed) return;
    observed = t;
    lastText = t.textContent;
    new MutationObserver(() => {
      if (t.textContent !== lastText) { lastText = t.textContent; if (!swapping) fades('pa-hold', true); }
    }).observe(t, { childList: true, subtree: true, characterData: true });
  }

  async function swap(c, key, img) {
    swapping = true;
    fades('pa-hold', true);
    try { const p = new Image(); p.src = c.photo; await Promise.race([p.decode(), wait(6000)]); } catch (e) { }
    const shown = new Promise((r) => { img.onload = r; img.onerror = r; });
    img.classList.add('pa-dev');
    href(img, c.photo);
    href(document.getElementById('pa-photo-bg'), c.photo);
    await Promise.race([shown, wait(1500)]);
    // 卡片 JSON 可能比畫面綁定的文字先到:等綁定文字也換成這一筆才顯示
    for (let i = 0; i < 40; i++) {
      const s = textOf('VAL_pa_sub');
      if (s && s.textContent.indexOf(String(c.sub || c.id)) >= 0) break;
      await wait(100);
    }
    await wait(150);
    img.__paKey = key;
    fitAll();
    drawXray();
    // 第一次排版與照片都好了才顯示(SVG 裡預設 opacity:0,避免腳本啟動前文字疊在一起)
    document.querySelectorAll('.pa-fade').forEach((e) => { e.style.opacity = ''; });
    fades('pa-hold', false);
    fades('pa-dim', false);
    swapping = false;
    setTimeout(() => img.classList.remove('pa-dev'), 150);
  }

  // ---------- JSON 透視模式 ----------
  function chip(g, b, lines) {
    const rect = document.createElementNS(NS, 'rect');
    Object.entries({ x: b.x, y: b.y, width: b.w, height: b.h, rx: 10, fill: '#0b1b33', 'fill-opacity': 1, stroke: '#7fe7ff', 'stroke-opacity': .55 }).forEach(([k, v]) => rect.setAttribute(k, v));
    g.appendChild(rect);
    const gap = 21, top = b.y + (b.h - gap * lines.length) / 2 + 16;
    lines.forEach((s, i) => {
      const t = document.createElementNS(NS, 'text');
      Object.entries({ x: b.x + 12, y: top + i * gap, 'font-size': 15, 'font-weight': i ? 400 : 700, fill: i ? '#ffffff' : '#7fe7ff', 'font-family': 'Consolas, monospace' }).forEach(([k, v]) => t.setAttribute(k, v));
      t.textContent = s;
      g.appendChild(t);
      const w = t.getComputedTextLength(), max = b.w - 24;
      if (w > max) t.setAttribute('font-size', Math.max(9, Math.floor(15 * max / w)));
    });
  }
  function drawXray() {
    const g = document.getElementById('pa-xray'), c = card;
    if (!g) return;
    g.style.display = xray ? '' : 'none';
    const lb = document.getElementById('pa-xr-lb');
    if (lb) lb.textContent = xray ? '關閉透視' : '透視 JSON';
    while (g.firstChild) g.removeChild(g.firstChild);
    if (!xray || !c || !c.raw) return;
    const r = c.raw, q = (v) => '"' + v + '"';
    chip(g, { x: 64, y: 112, w: 1154, h: 26 }, [c.api]);
    chip(g, { x: 690, y: 140, w: 528, h: 34 }, ['animal_kind ' + q(r.kind) + ' / animal_Variety ' + q(r.variety)]);
    chip(g, { x: 690, y: 182, w: 528, h: 92 }, [c.sinceField + ': ' + q(r.since), '→ tag ' + c.sinceTag, '→ 腳本算到今天 = 等家天數']);
    [['animal_sex', r.sex, 't_pa_sex'], ['animal_bodytype', r.body, 't_pa_body'], ['animal_age', r.age, 't_pa_age'],
     ['animal_colour', r.colour, 't_pa_colour'], ['animal_sterilization', r.ster, 't_pa_ster'], ['animal_bacterin', r.bact, 't_pa_bact']]
      .forEach(([path, raw, tag], i) => chip(g, { x: 690 + (i % 3) * 180, y: 314 + Math.floor(i / 3) * 96, w: 168, h: 84 }, [path, q(raw), '→ ' + tag]));
    chip(g, { x: 690, y: 512, w: 528, h: 108 }, ['shelter_name    → t_pa_shelter', 'shelter_tel     → t_pa_tel', 'shelter_address → t_pa_addr']);
    chip(g, { x: 126, y: 566, w: 470, h: 56 }, ['album_file → t_pa_photo', c.photo.split('/').pop()]);
  }
  // 官方認養資訊:開農業部全國動物收容管理系統的認養公告(個別動物沒有獨立網址)
  const OFFICIAL = 'https://www.pet.gov.tw/AnimalApp/AnnounceMent.aspx?PageType=Adopt';
  function wireOfficial() {
    const o = document.getElementById('pa-official');
    if (!o || o.__paOn) return;
    o.__paOn = true;
    const a = o.querySelector('a');
    if (a) { a.setAttribute('href', OFFICIAL); a.setAttribute('target', '_blank'); a.setAttribute('rel', 'noopener'); }
    o.style.cursor = 'pointer';
    o.addEventListener('click', (ev) => { ev.preventDefault(); ev.stopPropagation(); window.open(OFFICIAL, '_blank', 'noopener'); });
  }
  function wire() {
    const b = document.getElementById('pa-xr');
    if (b && !b.__paOn) {
      b.__paOn = true;
      b.addEventListener('click', () => { xray = !xray; drawXray(); });
    }
  }

  async function load() {
    try {
      const img = document.getElementById('pa-photo');
      if (!img) { observed = null; return; }
      if (!img.__paClean) { img.__paClean = true; cleanBaked(); }
      wire();
      wireOfficial();
      watch();
      const raw = await svc.$getTagForScript(null, 't_pad_json');
      if (!raw) return;
      const c = JSON.parse(raw);
      card = c;
      const key = c.id + '|' + c.push;
      if (swapping) return;
      if (img.__paKey !== key) { swap(c, key, img); return; }
      fades('pa-dim', !!c.busy);
      if (!c.busy) fades('pa-hold', false);
      fitAll();
    } catch (e) { }
  }
  load();
  setInterval(load, 600);
}
